import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        char[] s = new String(System.in.readAllBytes()).trim().toCharArray();
        // Adjacent same-parity swaps can only reorder digits inside a maximal same-parity run.
        for (int i = 0, j; i < s.length; i = j) {
            j = i + 1;
            while (j < s.length && (s[j] - '0') % 2 == (s[i] - '0') % 2) j++;
            Arrays.sort(s, i, j);
            // Sorted ascending, so reverse the run for descending order.
            for (int a = i, b = j - 1; a < b; a++, b--) {
                char t = s[a];
                s[a] = s[b];
                s[b] = t;
            }
        }
        System.out.print(new String(s) + "\n");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	var str string
	fmt.Fscan(bufio.NewReader(os.Stdin), &str)
	s := []byte(str)
	// Adjacent same-parity swaps can only reorder digits inside a maximal same-parity run.
	for i := 0; i < len(s); {
		j := i + 1
		for j < len(s) && (s[j]-'0')%2 == (s[i]-'0')%2 {
			j++
		}
		run := s[i:j]
		sort.Slice(run, func(a, b int) bool { return run[a] > run[b] })
		i = j
	}
	fmt.Println(string(s))
}
